"package main

import (
	"fmt"
	"net/http"
	"os"
	"os/exec"
	"runtime"
	"strings"
	"sync"
	"time"
)

var (
	guiMutex       sync.Mutex
	guiCmd         *exec.Cmd
	isHeadlessMode bool
)

// InitDesktopFlags checks command line arguments for headless/no-gui mode
func InitDesktopFlags() {
	for _, arg := range os.Args[1:] {
		low := strings.ToLower(arg)
		if low == "--headless" || low == "--no-gui" || low == "-headless" || low == "-no-gui" {
			isHeadlessMode = true
			break
		}
	}
}

// IsHeadless returns whether the application is configured to run without GUI window
func IsHeadless() bool {
	return isHeadlessMode
}

