"// GenerateLiquidsoapScript creates the player.liq script dynamically based on detected profile
func GenerateLiquidsoapScript(cfg *Config) error {
	profileName, tmplContent := DetectPlayoutProfile(cfg)
	LogLocal("INFO", "[Playout Engine] Aplicando Template Especializado: %s", profileName)
	activeProfileName = profileName

	// Check if a template file exists on disk in templates/liq/ to allow local overrides
	var diskTmplName string
	switch {
	case strings.HasPrefix(profileName, "LOCAL_ACERVO"):
		diskTmplName = "templates/liq/local_acervo.liq.tmpl"
	case strings.HasPrefix(profileName, "LOCAL_HYBRID"):
		diskTmplName = "templates/liq/local_hybrid.liq.tmpl"
	case strings.HasPrefix(profileName, "LOCAL_STREAMING"):
		diskTmplName = "templates/liq/local_streaming.liq.tmpl"
	case strings.HasPrefix(profileName, "SERVER_ACERVO"):
		diskTmplName = "templates/liq/server_acervo.liq.tmpl"
	case strings.HasPrefix(profileName, "SERVER_HYBRID"):
		diskTmplName = "templates/liq/server_hybrid.liq.tmpl"
	case strings.HasPrefix(profileName, "SERVER_STREAMING"):
		diskTmplName = "templates/liq/server_streaming.liq.tmpl"
	}

	if diskTmplName != "" {
		if content, err := os.ReadFile(diskTmplName); err == nil && len(content) > 0 {
			tmplContent = string(content)
		}
	}

	tmpl, err := template.New("player.liq").Parse(tmplContent)
	if err != nil {
		return err
	}

	// Ensure the parent directory of ScriptPath exists
	dir := filepath.Dir(cfg.ScriptPath)
	if err := os.MkdirAll(dir, 0755); err != nil {
		return err
	}

	var buf bytes.Buffer
	if err := tmpl.Execute(&buf, cfg); err != nil {
		return err
	}

	return os.WriteFile(cfg.ScriptPath, buf.Bytes(), 0644)
}"

