	// Liveness Watchdog: periodically verifies if Liquidsoap has stalled on safe_blank or 0s remaining
	go func() {
		time.Sleep(15 * time.Second)
		stallCounter := 0
		var lastTitle string
		for {
			time.Sleep(5 * time.Second)
			meta := fetchLiquidsoapMetadata()
			if len(meta) == 0 {
				continue
			}
			title := meta["title"]
			rem := meta["remaining"]
			if rem == "" {
				rem = meta["remaining_seconds"]
			}

			// Check if player is stuck on empty/safe_blank or title didn't advance past 0s
			if title == "" || title == "Sem reprodução" {
				stallCounter++
			} else if title == lastTitle && (rem == "0" || rem == "0.00" || rem == "0.0" || rem == "0.000") {
				stallCounter++
			} else {
				stallCounter = 0
				lastTitle = title
			}

			if stallCounter >= 3 { // 15 seconds of stall/silence
				LogLocal("WARNING", "[Watchdog] Detected audio playback stall (title='%s', rem='%s'). Triggering harbor skip to recover playout...", title, rem)
				stallCounter = 0
				harborPort := cfg.HarborPort
				if harborPort <= 0 {
					harborPort = 7000
				}
				resp, errSkip := http.Get(fmt.Sprintf("http://127.0.0.1:%d/skip", harborPort))
				if errSkip == nil {
					resp.Body.Close()
				}
			}
		}
	}()
}"

