"package main

import (
	"context"
	"database/sql"
	"fmt"
	"log"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
	_ "github.com/mattn/go-sqlite3"
)

func main() {
	databaseURL := "postgres://neoroute:@@Mo1isc00@@@192.168.15.250:5432/imc_server?sslmode=disable"
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	pool, err := pgxpool.New(ctx, databaseURL)
	if err == nil {
		defer pool.Close()
		fmt.Println("=== POSTGRES STORES ===")
		rows, err := pool.Query(ctx, `SELECT id, store_name, token, radio_type, audio_grid_id, is_active FROM stores WHERE token = 'token_lab_teste' OR store_name ILIKE '%sorocaba%' OR store_name ILIKE '%lab%'`)
		if err == nil {
			for rows.Next() {
				var id, name, token, radioType, gridID string
				var isActive bool
				_ = rows.Scan(&id, &name, &token, &radioType, &gridID, &isActive)
				fmt.Printf("Store: %s | Name: %s | Token: %s | RadioType: %s | GridID: %s | Active: %v\n", id, name, token, radioType, gridID, isActive)
			}
			rows.Close()
		}

		fmt.Println("\n=== POSTGRES GRIDS ===")
		rowsG, err := pool.Query(ctx, `SELECT id, name, sunday_schedule_id, monday_schedule_id FROM weekly_master_grids`)
		if err == nil {
			for rowsG.Next() {
				var id, name, sunSched, monSched string
				_ = rowsG.Scan(&id, &name, &sunSched, &monSched)
				fmt.Printf("Grid: %s | Name: %s | Sun: %s | Mon: %s\n", id, name, sunSched, monSched)
			}
			rowsG.Close()
		}

